#pragma config(Motor,  port3,        pressArmServo,  tmotorServoStandard, openLoop)
//*!!Code automatically generated by 'ROBOTC' configuration wizard               !!*//

/*
  Servo centering for the press arm (one servo, motor port 3).

  Sends the servo to the center (0) and holds it there until you press Stop
  or switch the robot off. Use it to (re)attach the arm at the right angle.

  How to use:
    1. Take the arm (or its shaft) off the servo, so the servo can turn freely.
    2. Download and press Start. The servo output turns to the center and stays there.
    3. While the program is running, slide the arm back on at the middle angle,
       halfway between "arm up" and "pressing the button".
    4. Press Stop, then run servo_angle_test.c to find the up and press values.
*/

task main()
{
    motor[pressArmServo] = 0;

    while(true)
        wait1Msec(100);
}
